let circleProfile=null,circleStore=null;
function mapsLink(address,label,directions=false){return `<a class="map-link" href="${escape(WCNext.mapURL(address,directions))}" target="_blank" rel="noopener noreferrer">⌖ ${escape(label)} ↗</a>`}
async function shareCircle(){const data={title:'Wakad Circle',text:'Your neighbourhood essentials, delivered or ready for pickup.',url:'https://wakad-circle.web.app/'};try{if(navigator.share)await navigator.share(data);else if(navigator.clipboard){await navigator.clipboard.writeText(data.url);notify('Shop link copied. Share it with your neighbours.')}else commerceModal('share',`<h2>Share your circle.</h2><p>Send this link to your neighbours.</p><input readonly aria-label="Shop link" value="${data.url}">`)}catch(e){if(e.name!=='AbortError')notify('Could not share. Please copy wakad-circle.web.app from your browser.')}}
showCircleAccount=function(){
 if(needAccount(showCircleAccount))return;
 const name=circleProfile?.displayName||'Neighbour',initial=name.slice(0,1).toUpperCase();
 commerceModal('account',`<section class="profile-hero"><span class="profile-avatar">${escape(initial)}</span><div><small>YOUR WAKAD CIRCLE</small><h2>${escape(name)}</h2><p>${escape(window.WKCloud.user.phoneNumber||'Phone verified')}</p></div></section><div class="profile-perks"><span>⌂ ₹25 delivery · free on ₹499+</span><span>♧ Free pickup · no minimum</span></div><div class="account-menu profile-menu"><button id="editprofile">♙ My profile <span>Edit →</span></button><button id="myorders">▤ My orders <span>Track & pay →</span></button><button id="myaddresses">⌖ Saved addresses <span>${savedAddresses.length} saved →</span></button><button id="profilepickup">♧ Pickup & service area <span>View →</span></button><button id="profileshare">↗ Share Wakad Circle <span>Invite →</span></button><button id="circlelogout">Sign out <span>↗</span></button></div><p class="form-note">Your phone number is verified. Your profile and addresses stay private to your account.</p>`);
 $('#editprofile').onclick=editCircleProfile;$('#myorders').onclick=showCustomerOrders;$('#myaddresses').onclick=()=>manageAddresses();$('#profileshare').onclick=shareCircle;$('#profilepickup').onclick=showPickupInfo;$('#circlelogout').onclick=async()=>{try{await window.WKCloud.signOut();$('#modal').close()}catch(e){notify(e.message)}};
};
function editCircleProfile(){commerceModal('profile',`<span class="eyebrow green">A LITTLE MORE YOU</span><h2>My profile</h2><form id="profileform"><label>Your name<input name="displayName" required minlength="2" maxlength="80" autocomplete="name" value="${escape(circleProfile?.displayName||'')}"></label><label>Verified mobile<input disabled value="${escape(window.WKCloud.user.phoneNumber||'')}"></label><p class="form-note">To use another mobile number, sign out and verify that number. Saved details belong to each verified account.</p><button class="primary wide">Save profile</button></form><button id="profileback" class="text-button wide">Back to my account</button>`);$('#profileback').onclick=showCircleAccount;$('#profileform').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;const data=Object.fromEntries(new FormData(event.target)),uid=window.WKCloud.user.uid;try{await window.WKCloud.saveProfile(data);if(window.WKCloud.user?.uid!==uid)return;circleProfile=data;showCircleAccount();notify('Profile saved')}catch(e){notify(e.message);button.disabled=false}}}
function showPickupInfo(){const address=circleStore?.pickupAddress||storeAddress;commerceModal('pickup-info',`<h2>Your local pickup spot.</h2><p>${escape(address)}</p>${mapsLink(address,address!==window.WC_STORE_ADDRESS?'Open pickup location in Google Maps':'View Wakad pickup area')}${circleStore?.contactPhone?`<p><a class="map-link" href="tel:${escape(circleStore.contactPhone)}">Call the store · ${escape(circleStore.contactPhone)}</a></p>`:''}<p class="form-note">Delivery currently serves PIN 411057. Delivery ₹25, free at ₹499. Pickup is always free with no minimum. Wait for the store to mark your order ready.</p><p class="form-note">${address!==window.WC_STORE_ADDRESS?'Check the store address before travelling.':'Ask the store for its exact shop location before travelling.'}</p>`)}
$('#signinbutton').onclick=showCircleAccount;
window.WK.receiveProfile=p=>{circleProfile=p;if($('#modal').open&&$('#modal').dataset.view==='account')showCircleAccount()};
window.WK.receiveStore=s=>{circleStore=s;if(s?.pickupAddress){storeAddress=s.pickupAddress;updateFulfillmentHeader()}renderStoreNotice()};
function renderStoreNotice(){let banner=$('#storenotice');if(!banner){banner=document.createElement('section');banner.id='storenotice';banner.className='store-notice';banner.setAttribute('role','status');$('#offers').before(banner)}if(!circleStore){banner.hidden=true;return}const now=new Date(Date.now()+330*60000),minute=now.getUTCHours()*60+now.getUTCMinutes(),closed=circleStore.paused||minute<circleStore.openMinute||minute>=circleStore.closeMinute;banner.hidden=!closed;banner.textContent=circleStore.paused?(circleStore.pauseMessage||'The store has paused new orders. Please check back soon.'):'The store is closed. You can browse now and order during opening hours.';const footer=$('footer small');if(footer){const fmt=n=>Math.floor(n/60).toString().padStart(2,'0')+':'+(n%60).toString().padStart(2,'0');footer.textContent='Wakad, Pune · '+fmt(circleStore.openMinute)+'–'+fmt(circleStore.closeMinute)+' IST'}}
setInterval(renderStoreNotice,60000);
const shareButton=document.createElement('button');shareButton.id='shareapp';shareButton.className='share-app';shareButton.setAttribute('aria-label','Share Wakad Circle');shareButton.innerHTML='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4M9 14l6 4"/></svg><span>Share shop</span>';shareButton.onclick=shareCircle;$('.utility-actions').append(shareButton);
